mapper.select:
SELECT d.idx
FROM dangerous_area d
LEFT JOIN trailgo_hazard_review r ON r.hazard_id = d.idx
WHERE d.da_lat BETWEEN #{minLat} AND #{maxLat}
  AND d.da_lon BETWEEN #{minLon} AND #{maxLon}
  AND NOT (COALESCE(r.is_active, 1) = 1
           AND r.merged_into IS NULL
           AND (r.expires_at IS NULL OR r.expires_at > CURRENT_TIMESTAMP)
           AND  IN ('PENDING', 'REVIEWING', 'APPROVED'))
LIMIT #{limit}
